package aaa;

import java.lang.invoke.*;

// invokedynamic call sites with a user bootstrap method, as Groovy compiles
// every call.  javac doesn't emit these, so the call sites are in a class
// assembled by hand (generated by a small script; version 52, with no
// branches, so it needs no StackMapTable):
//
//   static int f(int x)      { iload_0; invokedynamic twice(I)I; ireturn }
//   static boolean g(int x)  { iload_0; invokedynamic isBig(I)Z; ireturn }
//
// both bootstrapped by indysite.bsm.  The two call sites are at the same
// pc in different methods, and each must get its own target.  The
// bootstrap method gets a lookup on the class of the call site, and the
// target is invoked exactly: g's boolean result is a boolean.
public class indysite extends ClassLoader
{
    private static final byte[] SITES = new byte[] {
        -54,-2,-70,-66,0,0,0,52,0,26,1,0,18,97,97,97,47,105,110,100,121,115,105,116,101,36,83,105,116,101,115,7,0,1,1,0,16,106,97,118,97,47,108,97,110,103,47,79,98,106,101,99,116,7,0,3,1,0,12,97,97,97,47,105,110,100,121,115,105,116,101,7,0,5,1,0,3,98,115,109,1,0,115,40,76,106,97,118,97,47,108,97,110,103,47,105,110,118,111,107,101,47,77,101,116,104,111,100,72,97,110,100,108,101,115,36,76,111,111,107,117,112,59,76,106,97,118,97,47,108,97,110,103,47,83,116,114,105,110,103,59,76,106,97,118,97,47,108,97,110,103,47,105,110,118,111,107,101,47,77,101,116,104,111,100,84,121,112,101,59,41,76,106,97,118,97,47,108,97,110,103,47,105,110,118,111,107,101,47,67,97,108,108,83,105,116,101,59,12,0,7,0,8,10,0,6,0,9,15,6,0,10,1,0,5,116,119,105,99,101,1,0,4,40,73,41,73,12,0,12,0,13,18,0,0,0,14,1,0,5,105,115,66,105,103,1,0,4,40,73,41,90,12,0,16,0,17,18,0,0,0,18,1,0,4,67,111,100,101,1,0,16,66,111,111,116,115,116,114,97,112,77,101,116,104,111,100,115,1,0,1,102,1,0,4,40,73,41,73,1,0,1,103,1,0,4,40,73,41,90,0,33,0,2,0,4,0,0,0,0,0,2,0,9,0,22,0,23,0,1,0,20,0,0,0,19,0,1,0,1,0,0,0,7,26,-70,0,15,0,0,-84,0,0,0,0,0,9,0,24,0,25,0,1,0,20,0,0,0,19,0,1,0,1,0,0,0,7,26,-70,0,19,0,0,-84,0,0,0,0,0,1,0,21,0,0,0,6,0,1,0,11,0,0
    };

    static int twice(int x) { return 2 * x; }
    static boolean isBig(int x) { return x > 10; }
    static String lookupClasses = "";

    public static CallSite bsm(MethodHandles.Lookup lookup, String name, MethodType type) throws Exception
    {
        lookupClasses += lookup.lookupClass().getSimpleName() + " ";
        return new ConstantCallSite(MethodHandles.lookup().findStatic(indysite.class, name, type));
    }

    protected Class<?> findClass(String name) throws ClassNotFoundException
    {
        if (!name.equals("aaa.indysite$Sites")) throw new ClassNotFoundException(name);
        return defineClass(name, SITES, 0, SITES.length);
    }

    public static void main(String[] args) throws Exception
    {
        Class<?> c = new indysite().loadClass("aaa.indysite$Sites");
        Object f = c.getMethod("f", int.class).invoke(null, 21);
        Object g = c.getMethod("g", int.class).invoke(null, 50);
        Object f2 = c.getMethod("f", int.class).invoke(null, 4);
        String result = f + " " + g + " " + f2 + " " + lookupClasses.trim();
        System.out.println("42 true 8 indysite$Sites indysite$Sites".equals(result) ? "OK" : "FAIL: " + result);
    }
}
